/* NearMiss01Mapper.countUserSiteAuth */
SELECT
    COUNT(1)
FROM TB_USER_SITE_AUTH A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

/* NearMiss01Mapper.selectIncidentList */
SELECT

FROM TB_NEAR_MISS A
     LEFT OUTER JOIN TB_BAIM_VAL_D C
        ON (
            A.CMPNY_CD = C.CMPNY_CD
        AND C.BAIM_VAL_CD = 'COM002'
        AND A.PROCESS_CD = C.BAIM_VAL_D_CD
        AND C.USE_YN = 'Y'
        )
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.USE_YN = 'Y'

    AND A.SITE_CD = #{siteCd}


    AND A.REPORT_STATUS_CD = #{reportStatusCd}


    AND A.INCIDENT_TYPE_CD = #{incidentTypeCd}


    AND A.POTENTIAL_SEVERITY_CD = #{potentialSeverityCd}


    AND A.OCCUR_DTIME >= STR_TO_DATE(CONCAT(#{startDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s')


    AND A.OCCUR_DTIME <= STR_TO_DATE(CONCAT(#{endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s')

ORDER BY A.REPORT_STATUS_CD, A.OCCUR_DTIME DESC, A.NEAR_MISS_ID DESC

/* NearMiss01Mapper.selectIncidentInfo */
SELECT

FROM TB_NEAR_MISS A
     LEFT OUTER JOIN TB_BAIM_VAL_D C
        ON (
            A.CMPNY_CD = C.CMPNY_CD
        AND C.BAIM_VAL_CD = 'COM002'
        AND A.PROCESS_CD = C.BAIM_VAL_D_CD
        AND C.USE_YN = 'Y'
        )
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.NEAR_MISS_ID = #{nearMissId}
  AND A.USE_YN = 'Y'

/* NearMiss01Mapper.selectStatusCounts */
SELECT
    SUM(CASE WHEN A.REPORT_STATUS_CD = '100' THEN 1 ELSE 0 END) AS receivedCnt
  , SUM(CASE WHEN A.REPORT_STATUS_CD = '200' THEN 1 ELSE 0 END) AS reviewingCnt
  , SUM(CASE WHEN A.REPORT_STATUS_CD = '300' THEN 1 ELSE 0 END) AS actingCnt
  , SUM(CASE WHEN A.REPORT_STATUS_CD = '400' THEN 1 ELSE 0 END) AS completedCnt
FROM TB_NEAR_MISS A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.USE_YN = 'Y'

    AND A.SITE_CD = #{siteCd}


    AND A.INCIDENT_TYPE_CD = #{incidentTypeCd}


    AND A.POTENTIAL_SEVERITY_CD = #{potentialSeverityCd}


    AND A.OCCUR_DTIME >= STR_TO_DATE(CONCAT(#{startDate}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s')


    AND A.OCCUR_DTIME <= STR_TO_DATE(CONCAT(#{endDate}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s')

/* NearMiss01Mapper.selectReportStatus */
SELECT
    A.REPORT_STATUS_CD
FROM TB_NEAR_MISS A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.NEAR_MISS_ID = #{nearMissId}
  AND A.USE_YN = 'Y'

mapper.update:
/* NearMiss01Mapper.updateIncident */
UPDATE TB_NEAR_MISS
SET
    CAUSE_DESC           = #{causeDesc}
  , PREVENTION_DESC      = #{preventionDesc}
  , IMMEDIATE_ACTION_DESC = #{immediateActionDesc}
  , REVIEWER_ID          = #{gvUserCd}
  , REVIEW_DTIME         = NOW()
  , UPDATE_NO            = #{gvUserCd}
  , UPDATE_DATE          = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND NEAR_MISS_ID = #{nearMissId}
  AND USE_YN = 'Y'

/* NearMiss01Mapper.updateStatus */
UPDATE TB_NEAR_MISS
SET
    REPORT_STATUS_CD = #{reportStatusCd}
  , REVIEWER_ID      = #{gvUserCd}
  , REVIEW_DTIME     = NOW()

  , REJECT_REASON    = #{rejectReason}

  , UPDATE_NO        = #{gvUserCd}
  , UPDATE_DATE      = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND NEAR_MISS_ID = #{nearMissId}
  AND USE_YN = 'Y'

mapper.select:
/* NearMiss01Mapper.selectNextNearMissId */
SELECT
    CONCAT(
        'NM'
      , DATE_FORMAT(NOW(), '%Y%m%d')
      , LPAD(
            IFNULL(
                MAX(CAST(SUBSTR(A.NEAR_MISS_ID, 11, 3) AS UNSIGNED))
              , 0
            ) + 1
          , 3, '0'
        )
    )
FROM TB_NEAR_MISS A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.NEAR_MISS_ID LIKE CONCAT('NM', DATE_FORMAT(NOW(), '%Y%m%d'), '%')

mapper.insert:
/* NearMiss01Mapper.insertIncident */
INSERT INTO TB_NEAR_MISS
(
    CMPNY_CD
  , SITE_CD
  , NEAR_MISS_ID
  , INCIDENT_TYPE_CD
  , PROCESS_CD
  , OCCUR_DTIME
  , LOCATION_DESC
  , DESCRIPTION
  , POTENTIAL_SEVERITY_CD
  , IMMEDIATE_ACTION_DESC
  , REPORT_STATUS_CD
  , REPORTER_ID
  , REPORT_DTIME
  , SRC_PROCESS_CD
  , SRC_ASSESSMENT_CD
  , USE_YN
  , INSERT_NO
  , INSERT_DATE
)
VALUES
(
    #{gvCmpnyCd}
  , #{siteCd}
  , #{nearMissId}
  , #{incidentTypeCd}
  , #{processCd}
  , STR_TO_DATE(#{occurDtime}, '%Y-%m-%d %H:%i')
  , #{locationDesc}
  , #{description}
  , #{potentialSeverityCd}
  , #{immediateActionDesc}
  , '100'
  , #{gvUserCd}
  , NOW()
  , #{srcProcessCd}
  , #{srcAssessmentCd}
  , 'Y'
  , #{gvUserCd}
  , NOW()
)

