/* NearMiss01Mapper.countAssessment */
SELECT
    COUNT(1)
FROM TB_RISK_ASSESSMENT A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.PROCESS_CD = #{srcProcessCd}
  AND A.ASSESSMENT_CD = #{srcAssessmentCd}
  AND A.ASSESSMENT_STATUS NOT IN ('003', '004', '005')

/* NearMiss01Mapper.countAssessmentAny */
SELECT
    COUNT(1)
FROM TB_RISK_ASSESSMENT A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.PROCESS_CD = #{srcProcessCd}
  AND A.ASSESSMENT_CD = #{srcAssessmentCd}

mapper.update:
/* NearMiss01Mapper.transferAssessmentStatus */
UPDATE TB_RISK_ASSESSMENT
SET
    ASSESSMENT_STATUS = '005'
  , UPDATE_NO         = #{gvUserCd}
  , UPDATE_DATE       = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{srcProcessCd}
  AND ASSESSMENT_CD = #{srcAssessmentCd}
